/// Every deprecated region subtag that names a replacement, mapped onto it.
///
/// `BU` folds onto `MM`. A deprecated region ABSENT from here has no replacement and stays itself.
///
/// 6 rows, sorted. Generated into `REGION_PREFERRED`.
pub(crate) static REGION_PREFERRED: &[(Ascii<AREA>, &str)] = &[
  (Ascii::literal("BU"), "MM"),
  (Ascii::literal("DD"), "DE"),
  (Ascii::literal("FX"), "FR"),
  (Ascii::literal("TP"), "TL"),
  (Ascii::literal("YD"), "YE"),
  (Ascii::literal("ZR"), "CD"),
];

/// Every region subtag the registry has deprecated, whether or not it names a replacement.
///
/// `AN`, `CS`, `NT`, `SU` and `YU` are the ones that name none — a country that dissolved into
/// several has no single successor to fold onto.
///
/// 11 rows, sorted. Generated into `REGION_DEPRECATED`.
pub(crate) static REGION_DEPRECATED: &[&str] = &[
  "AN", "BU", "CS", "DD", "FX", "NT", "SU", "TP", "YD", "YU", "ZR",
];

/// The region ranges the registry reserves for private use, as inclusive bounds.
///
/// TWO of them, where a language and a script have one each.
///
/// 2 rows, sorted. Generated into `REGION_PRIVATE_USE`.
pub(crate) static REGION_PRIVATE_USE: &[(&str, &str)] = &[("QM", "QZ"), ("XA", "XZ")];

/// Every region subtag the registry reserves for private use INDIVIDUALLY, outside the ranges.
///
/// `AA` and `ZZ`, each a record of its own carrying the description `Private use`. A region is the
/// only subtag kind with any, which is why it is the only one whose private-use question is not a
/// range test alone — and the generator refuses a registry in which a language or a script grows
/// one.
///
/// 2 rows, sorted. Generated into `REGION_PRIVATE_USE_SUBTAGS`.
pub(crate) static REGION_PRIVATE_USE_SUBTAGS: &[&str] = &["AA", "ZZ"];

